/** Unit id (key in the unit table) -> icon key. Every unit has its own icon. */
export const UNIT_ICON_BY_ID: Record<string, string> = {
  'soldier': 'soldier', // Soldier
  'scout': 'scout', // Scout
  'bazooka': 'bazooka', // Bazooka
  'sniper': 'sniper', // Sniper
  'archer': 'archer', // Archer
  'javelin': 'javelin', // Javelin
  'horsearcher': 'horsearcher', // Horse archer
  'lightcavalry': 'lightcavalry', // Light cavalry
  'chariotarcher': 'chariotarcher', // Chariot archer
  'cohort': 'cohort', // Cohort
  'hoplite': 'hoplite', // Hoplite
  'elephant': 'elephant', // Elephant
  'barbarian': 'barbarian', // Barbarian
  'catapult': 'catapult', // Catapult
  'ballista': 'ballista', // Ballista
  'tank': 'tank', // Tank
  'general': 'general', // General
  'tower': 'tower', // Tower
  'dummy': 'dummy', // Dummy
  'peasant': 'peasant', // Peasant
  'builder': 'builder', // Builder
  'dude': 'dude', // Anthony
  'wolf': 'wolf', // Wolf
  'fighter': 'fighter', // Fighter
  'gunship': 'gunship', // Gunship
  'bomber': 'bomber', // Bomber
  'frigate': 'frigate', // Frigate
  'cruiser': 'cruiser', // Cruiser
  'dreadnought': 'dreadnought', // Dreadnought
  'u-mvf8ty84rdk3': 'cavalry', // Cavalry
  'u-mvf8vjffgpkd': 'general2', // General
  'u-mvgpbg68f593': 'scarecrow', // Scarecrow
  'u-mvkn6vl7l0zw': 'tower2', // Tower 2
  'u-mvlx87f1kk67': 'builder2', // Builder
  'u-mvr2vokzh3n3': 'recruit', // Recruit
  'u-mvun2x81vsl5': 'hangoverdude', // Hangover Anthony
  'u-mvuvhfewwv97': 'armoreddude', // Armored Anthony
  'u-mw3t85tpmhz2': 'armoredpeasant', // Armored peasant
  'u-mw4vuw6xnwnt': 'cohortdude', // Cohort Anthony
  'u-mwjio288uty1': 'heavycohort', // Heavy Cohort
  'u-mwjiue32r9rf': 'lightcavalry2', // Light cavalry
  'u-mwowcdhlpw7r': 'phalangites', // Phalangites
};

/** Fallback for unit ids created later: icon of the base role (role names == base unit ids). */
function iconKeyFor(type: UnitType): string {
  const id = type as unknown as string;
  return UNIT_ICON_BY_ID[id] ?? UNIT_ICON_BY_ID[roleOf(type) as unknown as string] ?? 'soldier';
}

/** Raw path data for a unit (24x24 grid). Handy for HTML/CSS or <svg viewBox="0 0 24 24"> catalog swatches. */
export function unitIconPath(type: UnitType): string {
  return UNIT_ICON_PATHS[iconKeyFor(type)];
}

/**
 * Same signature and output contract as the old pieceIconSvg(type, size): a <g class="piece-icon"> centred on 0,0
 * whose glyph spans `size` px. Old: scale(size/20) on a -10..10 glyph. New: scale(size/24) on a -12..12 glyph
 * (the translate re-centres the 0..24 grid). Visual extent is ~22/24 of the box, close to the old ~19/20.
 */
export function pieceIconSvg(type: UnitType, size = 16): string {
  const s = size / 24;
  return `<g class="piece-icon" transform="scale(${s}) translate(-12 -12)"><path d="${unitIconPath(type)}"/></g>`;
}

/** Standalone <svg> for catalogs/menus, colour via CSS `color`. */
export function unitIconSvg(type: UnitType, px = 24, className = 'unit-icon'): string {
  return `<svg class="${className}" viewBox="0 0 24 24" width="${px}" height="${px}" fill="currentColor" aria-hidden="true"><path d="${unitIconPath(type)}"/></svg>`;
}
